class Solution {
    public String longestPalindrome(String s) {
        int n = s.length();
        for (int length = n; length >= 1; length--) {
            for (int start = 0; start + length <= n; start++) {
                int end = start + length - 1;
                if (isPalindrome(s, start, end)) {
                    return s.substring(start, end + 1);
                }
            }
        }
        return "";
    }

    private boolean isPalindrome(String s, int left, int right) {
        while (left < right) {
            if (s.charAt(left) != s.charAt(right)) {
                return false;
            }
            left++;
            right--;
        }
        return true;
    }
}

class Solution {
    public String longestPalindrome(String s) {
        int n = s.length();
        int bestStart = 0;
        int bestLength = 1;
        for (int center = 0; center < n; center++) {
            int oddLength = expand(s, center, center);
            if (oddLength > bestLength) {
                bestStart = center - oddLength / 2;
                bestLength = oddLength;
            }

            int evenLength = expand(s, center, center + 1);
            if (evenLength > bestLength) {
                bestStart = center - evenLength / 2 + 1;
                bestLength = evenLength;
            }
        }
        return s.substring(bestStart, bestStart + bestLength);
    }

    private int expand(String s, int left, int right) {
        while (left >= 0 && right < s.length() && s.charAt(left) == s.charAt(right)) {
            left--;
            right++;
        }
        return right - left - 1;
    }
}

class Solution {
    public String longestPalindrome(String s) {
        int n = s.length();
        boolean[][] palindrome = new boolean[n][n];
        int bestStart = 0;
        int bestLength = 1;

        for (int length = 1; length <= n; length++) {
            for (int start = 0; start + length <= n; start++) {
                int end = start + length - 1;
                if (s.charAt(start) == s.charAt(end)
                        && (length <= 2 || palindrome[start + 1][end - 1])) {
                    palindrome[start][end] = true;
                    if (length > bestLength) {
                        bestStart = start;
                        bestLength = length;
                    }
                }
            }
        }
        return s.substring(bestStart, bestStart + bestLength);
    }
}

class Solution {
    public String longestPalindrome(String s) {
        int n = s.length();
        char[] transformed = new char[n * 2 + 3];
        transformed[0] = '^';
        int index = 1;
        for (int i = 0; i < n; i++) {
            transformed[index++] = '#';
            transformed[index++] = s.charAt(i);
        }
        transformed[index++] = '#';
        transformed[index] = '$';

        int[] radius = new int[transformed.length];
        int center = 0;
        int right = 0;
        int bestCenter = 0;
        int bestLength = 0;

        for (int i = 1; i < transformed.length - 1; i++) {
            int mirror = 2 * center - i;
            if (i < right) {
                radius[i] = Math.min(right - i, radius[mirror]);
            }
            while (transformed[i + 1 + radius[i]] == transformed[i - 1 - radius[i]]) {
                radius[i]++;
            }
            if (i + radius[i] > right) {
                center = i;
                right = i + radius[i];
            }
            if (radius[i] > bestLength) {
                bestLength = radius[i];
                bestCenter = i;
            }
        }

        int start = (bestCenter - bestLength) / 2;
        return s.substring(start, start + bestLength);
    }
}

class Solution {
    public String longestPalindrome(String s) {
        int n = s.length();
        String reversed = new StringBuilder(s).reverse().toString();
        int[][] dp = new int[n + 1][n + 1];
        int bestStart = 0;
        int bestLength = 1;

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (s.charAt(i - 1) != reversed.charAt(j - 1)) {
                    continue;
                }
                dp[i][j] = dp[i - 1][j - 1] + 1;
                int originalStart = n - j;
                int length = i - originalStart;
                if (originalStart >= 0 && length > bestLength && length <= dp[i][j]) {
                    bestStart = originalStart;
                    bestLength = length;
                }
            }
        }
        return s.substring(bestStart, bestStart + bestLength);
    }
}
